import os
import sys

print("CWD:", os.getcwd())
for root, dirs, files in os.walk(os.getcwd()):
    depth = root.replace(os.getcwd(), "").count(os.sep)
    if depth > 3:
        continue
    print("DIR:", root)
    for f in files:
        full = os.path.join(root, f)
        try:
            size = os.path.getsize(full)
        except OSError:
            size = -1
        print("   FILE:", f, "size:", size)
